) AS v(restaurant_name, food_name, description, price, image, category)
INNER JOIN Restaurants r
    ON r.name = v.restaurant_name
WHERE NOT EXISTS (
    SELECT 1
    FROM MenuItems mi
    WHERE mi.restaurant_id = r.id
      AND mi.food_name = v.food_name
      AND mi.category = v.category
);

